// === Tab: mySketch ===
let particles = [];
let num = 2000; // 粒子の数（重ければ1000に減らしてください）
let noiseScale = 0.01;

function setup() {
	createCanvas(windowWidth, windowHeight);
	background(10); // 背景色（ほぼ黒）

	// 粒子を初期化
	for(let i = 0; i < num; i ++) {
		particles.push(createVector(random(width), random(height)));
	}
}

function draw() {
	// 軌跡を残すために薄く背景を塗り重ねる
	background(0, 10);

	for(let i = 0; i < num; i ++) {
		let p = particles[i];

		// 位置によって色を変える（高度に見えるポイント）
		let r = map(p.x, 0, width, 50, 255);
		let g = map(p.y, 0, height, 50, 255);
		let b = map(dist(width/2, height/2, p.x, p.y), 0, width/2, 255, 50);
		stroke(r, g, b, 200);
		strokeWeight(1.5);

		point(p.x, p.y);

		// ノイズを使って有機的な動きを作る
		let n = noise(p.x * noiseScale, p.y * noiseScale, frameCount * 0.005);
		let a = TWO_PI * n; // 角度を決定

		// マウスの位置で動きに変化を与える（インタラクション要素）
		if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) {
			a = atan2((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - p.y, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - p.x); // マウスに吸い寄せられる
		}

		p.x += cos(a) * 2;
		p.y += sin(a) * 2;

		// 画面外に出たらランダムな位置に戻す
		if(!onScreen(p)) {
			p.x = random(width);
			p.y = random(height);
		}
	}
}

// 画面内判定
function onScreen(v) {
	return v.x >= 0 && v.x <= width && v.y >= 0 && v.y <= height;
}

// ウィンドウサイズが変わったらキャンバスも合わせる
function windowResized() {
	resizeCanvas(windowWidth, windowHeight);
	background(10);
}

